      out.write("<!-- ===== INLINE JAVASCRIPT ===== -->\r\n");
      out.write("<script>\r\n");
      out.write("    /* =============================================\r\n");
      out.write("       CAPTCHA GENERATION (Client-side fallback)\r\n");
