      out.write("\r\n");
      out.write("    (function initCaptcha() {\r\n");
      out.write("        var captchaTextEl = document.getElementById('captchaText');\r\n");
      out.write("        // If server already set the captcha text content, use server mode\r\n");
      out.write("        if (captchaTextEl && captchaTextEl.textContent.trim().length > 0) {\r\n");
      out.write("            serverCaptchaPresent = true;\r\n");
      out.write("            clientCaptchaValue = captchaTextEl.textContent.trim();\r\n");
      out.write("        } else {\r\n");
      out.write("            generateClientCaptcha();\r\n");
      out.write("        }\r\n");
      out.write("    })();\r\n");
      out.write("\r\n");
      out.write("    function generateClientCaptcha() {\r\n");
      out.write("        var result = '';\r\n");
      out.write("        for (var i = 0; i < 6; i++) {\r\n");
      out.write("            result += CAPTCHA_CHARS.charAt(Math.floor(Math.random() * CAPTCHA_CHARS.length));\r\n");
      out.write("        }\r\n");
