      out.write("        btn.style.transform = 'rotate(360deg)';\r\n");
      out.write("        btn.style.transition = 'transform 0.4s ease';\r\n");
      out.write("        setTimeout(function() {\r\n");
      out.write("            btn.style.transform = '';\r\n");
      out.write("            btn.style.transition = '';\r\n");
      out.write("        }, 500);\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    /* =============================================\r\n");
      out.write("       PASSWORD VISIBILITY TOGGLE\r\n");
      out.write("       ============================================= */\r\n");
      out.write("    var eyeSvg = '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\r\n");
      out.write("    var eyeOffSvg = '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>';\r\n");
      out.write("\r\n");
      out.write("    function togglePass(inputId, iconId) {\r\n");
      out.write("        var inp = document.getElementById(inputId);\r\n");
      out.write("        var icon = document.getElementById(iconId);\r\n");
      out.write("        if (inp.type === 'password') {\r\n");
      out.write("            inp.type = 'text';\r\n");
      out.write("            icon.innerHTML = eyeOffSvg;\r\n");
      out.write("        } else {\r\n");
      out.write("            inp.type = 'password';\r\n");
      out.write("            icon.innerHTML = eyeSvg;\r\n");
      out.write("        }\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    /* =============================================\r\n");
      out.write("       PASSWORD STRENGTH INDICATOR\r\n");
      out.write("       ============================================= */\r\n");
      out.write("    var strengthBar = document.getElementById('strengthBar');\r\n");
      out.write("    var strengthText = document.getElementById('strengthText');\r\n");
      out.write("\r\n");
      out.write("    document.getElementById('password').addEventListener('input', function() {\r\n");
      out.write("        var val = this.value;\r\n");
      out.write("        var score = calcPasswordStrength(val);\r\n");
      out.write("        var levels = [\r\n");
      out.write("            { label: '',       color: '#e5e7eb', width: '0%'   },\r\n");
      out.write("            { label: 'Weak',   color: '#ef4444', width: '25%'  },\r\n");
      out.write("            { label: 'Fair',   color: '#f97316', width: '50%'  },\r\n");
      out.write("            { label: 'Good',   color: '#eab308', width: '75%'  },\r\n");
      out.write("            { label: 'Strong', color: '#22c55e', width: '100%' }\r\n");
      out.write("        ];\r\n");
      out.write("        var level = levels[score];\r\n");
      out.write("        strengthBar.style.width = level.width;\r\n");
      out.write("        strengthBar.style.backgroundColor = level.color;\r\n");
      out.write("        strengthText.textContent = score > 0 ? level.label : '';\r\n");
      out.write("        strengthText.style.color = level.color;\r\n");
      out.write("\r\n");
