      out.write("        if (confVal.length > 0) checkPasswordMatch();\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    function calcPasswordStrength(pwd) {\r\n");
      out.write("        if (!pwd || pwd.length === 0) return 0;\r\n");
      out.write("        var score = 0;\r\n");
      out.write("        if (pwd.length >= 8)  score++;\r\n");
      out.write("        if (pwd.length >= 12) score++;\r\n");
      out.write("        if (/[A-Z]/.test(pwd) && /[a-z]/.test(pwd)) score++;\r\n");
      out.write("        if (/[0-9]/.test(pwd)) score++;\r\n");
      out.write("        if (/[^A-Za-z0-9]/.test(pwd)) score++;\r\n");
      out.write("        if (score <= 1) return 1;\r\n");
      out.write("        if (score === 2) return 2;\r\n");
      out.write("        if (score === 3) return 3;\r\n");
      out.write("        return 4;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    /* =============================================\r\n");
      out.write("       PASSWORD MATCH CHECK\r\n");
      out.write("       ============================================= */\r\n");
      out.write("    var matchMsg = document.getElementById('matchMsg');\r\n");
      out.write("\r\n");
      out.write("    document.getElementById('confirmPassword').addEventListener('blur', checkPasswordMatch);\r\n");
      out.write("    document.getElementById('confirmPassword').addEventListener('input', function() {\r\n");
      out.write("        if (this.value.length > 0) checkPasswordMatch();\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    function checkPasswordMatch() {\r\n");
      out.write("        var pwd  = document.getElementById('password').value;\r\n");
      out.write("        var conf = document.getElementById('confirmPassword').value;\r\n");
      out.write("        var confInput = document.getElementById('confirmPassword');\r\n");
      out.write("        if (conf.length === 0) {\r\n");
      out.write("            matchMsg.textContent = '';\r\n");
      out.write("            matchMsg.className = 'match-msg';\r\n");
      out.write("            return;\r\n");
      out.write("        }\r\n");
      out.write("        if (pwd === conf) {\r\n");
      out.write("            matchMsg.textContent = 'Passwords match';\r\n");
      out.write("            matchMsg.className = 'match-msg match-ok';\r\n");
      out.write("            confInput.classList.remove('input-error');\r\n");
      out.write("            confInput.classList.add('input-success');\r\n");
      out.write("            hideFieldError('confirmPasswordError');\r\n");
      out.write("        } else {\r\n");
      out.write("            matchMsg.textContent = 'Passwords do not match';\r\n");
      out.write("            matchMsg.className = 'match-msg match-fail';\r\n");
      out.write("            confInput.classList.remove('input-success');\r\n");
      out.write("        }\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    /* =============================================\r\n");
      out.write("       MOBILE NUMBER: DIGITS ONLY, MAX 10\r\n");
