      out.write("    function showFieldError(inputId, errorId, message) {\r\n");
      out.write("        var inp = document.getElementById(inputId);\r\n");
      out.write("        var err = document.getElementById(errorId);\r\n");
      out.write("        if (inp) inp.classList.add('input-error');\r\n");
      out.write("        if (err) {\r\n");
      out.write("            if (message) err.textContent = message;\r\n");
      out.write("            err.classList.add('visible');\r\n");
      out.write("        }\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    function hideFieldError(errorId) {\r\n");
      out.write("        var err = document.getElementById(errorId);\r\n");
