      out.write("    document.getElementById('registerForm').addEventListener('submit', function(e) {\r\n");
      out.write("        e.preventDefault();\r\n");
      out.write("\r\n");
      out.write("        var valid = true;\r\n");
      out.write("        var firstErrorMsg = '';\r\n");
      out.write("\r\n");
      out.write("        function require(inputId, errorId, message) {\r\n");
