      out.write("        } else if (!emailRegex.test(emailVal)) {\r\n");
      out.write("            showFieldError('email', 'emailError', 'Enter a valid email address.');\r\n");
      out.write("            if (valid) firstErrorMsg = 'Enter a valid email address.';\r\n");
